CREATE TYPE "Role" AS ENUM ('OWNER','ADMIN','DEVELOPER','VIEWER');
CREATE TYPE "Environment" AS ENUM ('DEVELOPMENT','STAGING','PRODUCTION');
CREATE TYPE "ProjectStatus" AS ENUM ('ACTIVE','ARCHIVED');
CREATE TYPE "ApiKeyStatus" AS ENUM ('ACTIVE','REVOKED');
CREATE TYPE "EntitlementType" AS ENUM ('BOOLEAN','LIMIT','VALUE');
CREATE TYPE "ViolationStatus" AS ENUM ('OPEN','ACKNOWLEDGED','RESOLVED','IGNORED');
CREATE TYPE "Severity" AS ENUM ('CRITICAL','HIGH','MEDIUM','LOW');
CREATE TYPE "ObservationSource" AS ENUM ('SDK','SYNTHETIC','MANUAL');
CREATE TYPE "TestRunStatus" AS ENUM ('QUEUED','RUNNING','PASSED','FAILED','ERROR');
CREATE TYPE "TestResultStatus" AS ENUM ('PASS','FAIL','ERROR','SKIPPED');
CREATE TYPE "IntegrationProvider" AS ENUM ('STRIPE');
CREATE TYPE "IntegrationStatus" AS ENUM ('CONNECTED','DISCONNECTED','ERROR');
CREATE TYPE "WebhookStatus" AS ENUM ('RECEIVED','PROCESSING','PROCESSED','IGNORED','FAILED');
CREATE TYPE "NotificationStatus" AS ENUM ('PENDING','SENT','FAILED');

CREATE TABLE "User" ("id" text primary key,"email" text not null unique,"passwordHash" text not null,"emailVerifiedAt" timestamptz,"createdAt" timestamptz not null default now(),"updatedAt" timestamptz not null default now());
CREATE TABLE "Session" ("id" text primary key,"userId" text not null references "User"("id") on delete cascade,"tokenHash" text not null unique,"csrfTokenHash" text not null,"expiresAt" timestamptz not null,"createdAt" timestamptz not null default now(),"lastSeenAt" timestamptz not null default now());
CREATE INDEX "Session_userId_expiresAt_idx" ON "Session"("userId","expiresAt");
CREATE TABLE "PasswordResetToken" ("id" text primary key,"userId" text not null references "User"("id") on delete cascade,"tokenHash" text not null unique,"purpose" text not null default 'password_reset',"expiresAt" timestamptz not null,"usedAt" timestamptz,"createdAt" timestamptz not null default now());
CREATE INDEX "PasswordResetToken_userId_expiresAt_idx" ON "PasswordResetToken"("userId","expiresAt");
CREATE TABLE "Organization" ("id" text primary key,"name" text not null,"slug" text not null unique,"createdAt" timestamptz not null default now(),"updatedAt" timestamptz not null default now());
CREATE TABLE "Membership" ("id" text primary key,"organizationId" text not null references "Organization"("id") on delete cascade,"userId" text not null references "User"("id") on delete cascade,"role" "Role" not null,"createdAt" timestamptz not null default now(),unique("organizationId","userId"));
CREATE INDEX "Membership_userId_idx" ON "Membership"("userId");
CREATE TABLE "Project" ("id" text primary key,"organizationId" text not null references "Organization"("id") on delete cascade,"name" text not null,"environment" "Environment" not null,"status" "ProjectStatus" not null default 'ACTIVE',"createdAt" timestamptz not null default now(),"updatedAt" timestamptz not null default now(),unique("organizationId","name"));
CREATE INDEX "Project_organizationId_environment_idx" ON "Project"("organizationId","environment");
CREATE TABLE "ApiKey" ("id" text primary key,"organizationId" text not null references "Organization"("id") on delete cascade,"projectId" text not null references "Project"("id") on delete cascade,"label" text not null,"prefix" text not null,"secretHash" text not null,"fingerprint" text not null,"environment" "Environment" not null,"status" "ApiKeyStatus" not null default 'ACTIVE',"createdAt" timestamptz not null default now(),"revokedAt" timestamptz,"rotatedFromId" text,"lastUsedAt" timestamptz);
CREATE INDEX "ApiKey_projectId_status_idx" ON "ApiKey"("projectId","status"); CREATE INDEX "ApiKey_prefix_status_idx" ON "ApiKey"("prefix","status"); CREATE INDEX "ApiKey_organizationId_idx" ON "ApiKey"("organizationId");
CREATE TABLE "Customer" ("id" text primary key,"organizationId" text not null references "Organization"("id") on delete cascade,"projectId" text not null references "Project"("id") on delete cascade,"externalCustomerId" text not null,"emailHash" text,"metadata" jsonb,"createdAt" timestamptz not null default now(),"updatedAt" timestamptz not null default now(),unique("projectId","externalCustomerId"));
CREATE INDEX "Customer_organizationId_externalCustomerId_idx" ON "Customer"("organizationId","externalCustomerId");
CREATE TABLE "Feature" ("id" text primary key,"organizationId" text not null references "Organization"("id") on delete cascade,"key" text not null,"name" text not null,"type" "EntitlementType" not null,"description" text,"createdAt" timestamptz not null default now(),"updatedAt" timestamptz not null default now(),unique("organizationId","key"));
CREATE TABLE "Plan" ("id" text primary key,"organizationId" text not null references "Organization"("id") on delete cascade,"name" text not null,"key" text not null,"createdAt" timestamptz not null default now(),"updatedAt" timestamptz not null default now(),unique("organizationId","key"));
CREATE TABLE "PlanEntitlement" ("id" text primary key,"planId" text not null references "Plan"("id") on delete cascade,"featureId" text not null references "Feature"("id") on delete cascade,"value" jsonb not null,"createdAt" timestamptz not null default now(),unique("planId","featureId"));
CREATE TABLE "CustomerSubscription" ("id" text primary key,"customerId" text not null unique references "Customer"("id") on delete cascade,"planId" text not null references "Plan"("id") on delete restrict,"provider" text,"providerSubscriptionId" text,"status" text not null,"effectiveAt" timestamptz not null,"providerCreatedAt" timestamptz,"version" integer not null default 0,"metadata" jsonb);
CREATE INDEX "CustomerSubscription_providerSubscriptionId_idx" ON "CustomerSubscription"("providerSubscriptionId");
CREATE TABLE "ExpectedEntitlement" ("id" text primary key,"customerId" text not null references "Customer"("id") on delete cascade,"planId" text references "Plan"("id") on delete set null,"featureId" text not null references "Feature"("id") on delete cascade,"value" jsonb not null,"source" text not null,"effectiveAt" timestamptz not null default now(),"createdAt" timestamptz not null default now(),"updatedAt" timestamptz not null default now(),unique("customerId","featureId"));
CREATE INDEX "ExpectedEntitlement_customerId_effectiveAt_idx" ON "ExpectedEntitlement"("customerId","effectiveAt");
CREATE TABLE "ObservedDecision" ("id" text primary key,"organizationId" text not null references "Organization"("id") on delete cascade,"projectId" text not null references "Project"("id") on delete cascade,"customerId" text not null references "Customer"("id") on delete cascade,"featureId" text references "Feature"("id") on delete set null,"featureKey" text not null,"allowed" boolean not null,"value" jsonb,"plan" text,"used" integer,"limit" integer,"metadata" jsonb,"source" "ObservationSource" not null,"requestId" text,"observedAt" timestamptz not null,"receivedAt" timestamptz not null default now());
CREATE INDEX "ObservedDecision_project_customer_feature_observedAt_idx" ON "ObservedDecision"("projectId","customerId","featureKey","observedAt"); CREATE INDEX "ObservedDecision_organization_observedAt_idx" ON "ObservedDecision"("organizationId","observedAt");
CREATE TABLE "Violation" ("id" text primary key,"organizationId" text not null references "Organization"("id") on delete cascade,"projectId" text not null references "Project"("id") on delete cascade,"customerId" text not null references "Customer"("id") on delete cascade,"featureId" text references "Feature"("id") on delete set null,"featureKey" text not null,"expectedValue" jsonb,"observedValue" jsonb,"severity" "Severity" not null,"status" "ViolationStatus" not null default 'OPEN',"firstDetectedAt" timestamptz not null,"lastDetectedAt" timestamptz not null,"occurrenceCount" integer not null default 1,"source" text not null,"requestId" text,"createdAt" timestamptz not null default now(),"updatedAt" timestamptz not null default now());
CREATE INDEX "Violation_project_status_severity_idx" ON "Violation"("projectId","status","severity"); CREATE INDEX "Violation_customer_feature_status_idx" ON "Violation"("customerId","featureKey","status");
CREATE TABLE "ViolationOccurrence" ("id" text primary key,"violationId" text not null references "Violation"("id") on delete cascade,"expectedValue" jsonb,"observedValue" jsonb,"source" text not null,"requestId" text,"observedAt" timestamptz not null,"createdAt" timestamptz not null default now());
CREATE INDEX "ViolationOccurrence_violationId_createdAt_idx" ON "ViolationOccurrence"("violationId","createdAt");
CREATE TABLE "TestScenario" ("id" text primary key,"organizationId" text not null references "Organization"("id") on delete cascade,"projectId" text not null references "Project"("id") on delete cascade,"name" text not null,"key" text not null,"description" text,"definition" jsonb not null,"createdAt" timestamptz not null default now(),"updatedAt" timestamptz not null default now(),unique("projectId","key"));
CREATE TABLE "TestRun" ("id" text primary key,"organizationId" text not null references "Organization"("id") on delete cascade,"projectId" text not null references "Project"("id") on delete cascade,"scenarioId" text not null references "TestScenario"("id") on delete cascade,"status" "TestRunStatus" not null default 'QUEUED',"startedAt" timestamptz,"finishedAt" timestamptz,"summary" jsonb,"createdAt" timestamptz not null default now());
CREATE INDEX "TestRun_projectId_createdAt_idx" ON "TestRun"("projectId","createdAt");
CREATE TABLE "TestResult" ("id" text primary key,"testRunId" text not null references "TestRun"("id") on delete cascade,"step" integer not null,"name" text not null,"status" "TestResultStatus" not null,"expected" jsonb,"observed" jsonb,"error" text,"durationMs" integer,"createdAt" timestamptz not null default now());
CREATE INDEX "TestResult_testRunId_step_idx" ON "TestResult"("testRunId","step");
CREATE TABLE "Integration" ("id" text primary key,"organizationId" text not null references "Organization"("id") on delete cascade,"provider" "IntegrationProvider" not null,"status" "IntegrationStatus" not null default 'DISCONNECTED',"environment" "Environment" not null,"accountIdentifier" text,"secretCiphertext" text,"metadata" jsonb,"lastWebhookAt" timestamptz,"webhookFailures" integer not null default 0,"lastSyncAt" timestamptz,"createdAt" timestamptz not null default now(),"updatedAt" timestamptz not null default now(),unique("organizationId","provider","environment"));
CREATE TABLE "WebhookEvent" ("id" text primary key,"organizationId" text not null references "Organization"("id") on delete cascade,"projectId" text not null references "Project"("id") on delete cascade,"integrationId" text references "Integration"("id") on delete set null,"provider" text not null,"providerEventId" text not null,"eventType" text not null,"providerCreatedAt" timestamptz,"receivedAt" timestamptz not null default now(),"processedAt" timestamptz,"status" "WebhookStatus" not null default 'RECEIVED',"payloadHash" text not null,"error" text,"payload" jsonb,unique("provider","providerEventId"));
CREATE INDEX "WebhookEvent_projectId_receivedAt_idx" ON "WebhookEvent"("projectId","receivedAt");
CREATE TABLE "AuditLog" ("id" text primary key,"organizationId" text not null references "Organization"("id") on delete cascade,"projectId" text references "Project"("id") on delete set null,"actorUserId" text references "User"("id") on delete set null,"action" text not null,"resource" text not null,"resourceId" text,"ipAddress" text,"requestId" text,"metadata" jsonb,"createdAt" timestamptz not null default now());
CREATE INDEX "AuditLog_organizationId_createdAt_idx" ON "AuditLog"("organizationId","createdAt"); CREATE INDEX "AuditLog_resource_resourceId_idx" ON "AuditLog"("resource","resourceId");
CREATE TABLE "Notification" ("id" text primary key,"organizationId" text not null references "Organization"("id") on delete cascade,"type" text not null,"status" "NotificationStatus" not null default 'PENDING',"channel" text not null,"recipient" text,"subject" text,"body" text not null,"metadata" jsonb,"createdAt" timestamptz not null default now(),"sentAt" timestamptz,"error" text);
CREATE INDEX "Notification_organizationId_status_createdAt_idx" ON "Notification"("organizationId","status","createdAt");
